patch:
diff --git a/src/app/app/payroll/payroll-workflow.css b/src/app/app/payroll/payroll-workflow.css
index 984a90a..c794c43 100644
--- a/src/app/app/payroll/payroll-workflow.css
+++ b/src/app/app/payroll/payroll-workflow.css
@@ -185,3 +185,9 @@ html body .app-shell.nevora-portal .page-frame .payroll-workflow :is(.pw-documen

 /* TC-P4-23: the payday line follows the kit callout floor; filenames are TC-B32. */
 html body .app-shell.nevora-portal .page-frame .payroll-workflow .pw-statements header p { font: var(--nv-t-callout); }
+
+/* TC-RC-PAYROLL-01: desktop next-step guidance follows the kit's readable, scalable roles. */
+@media (min-width: 761px) and (not ((max-height: 430px) and (orientation: landscape) and (pointer: coarse))) {
+  html body .app-shell.nevora-portal .page-frame .payroll-workflow .pw-workflow-guidance { font: var(--nv-t-callout); }
+  html body .app-shell.nevora-portal .page-frame .payroll-workflow .pw-workflow-guidance strong { font: var(--nv-t-label); }
+}
